INSERT INTO `wp_options` VALUES (591,'_transient_4792','O:7:\"WP_Post\":24:{s:2:\"ID\";i:4792;s:11:\"post_author\";s:1:\"1\";s:9:\"post_date\";s:19:\"2024-10-14 16:22:38\";s:13:\"post_date_gmt\";s:19:\"2024-10-14 16:22:38\";s:12:\"post_content\";s:6442:\"<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"66.66%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:66.66%\"><!-- wp:image {\"lightbox\":{\"enabled\":true},\"width\":\"649px\",\"height\":\"auto\",\"aspectRatio\":\"1.7777777777777777\",\"scale\":\"cover\",\"sizeSlug\":\"large\",\"linkDestination\":\"none\",\"align\":\"center\",\"style\":{\"color\":{}}} -->\n<figure class=\"wp-block-image aligncenter size-large is-resized\"><img src=\"/wp-content/uploads/tower/Elstree.jpg\" alt=\"\" style=\"aspect-ratio:1.7777777777777777;object-fit:cover;width:649px;height:auto\"/></figure>\n<!-- /wp:image --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"33.33%\"} -->\n<div class=\"wp-block-column\" style=\"flex-basis:33.33%\"><!-- wp:buttons {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|superbspacing-xsmall\",\"bottom\":\"var:preset|spacing|superbspacing-xsmall\"},\"blockGap\":\"var:preset|spacing|superbspacing-medium\"}},\"layout\":{\"type\":\"flex\",\"orientation\":\"horizontal\"}} -->\n<div class=\"wp-block-buttons\" style=\"margin-top:var(--wp--preset--spacing--superbspacing-xsmall);margin-bottom:var(--wp--preset--spacing--superbspacing-xsmall)\"><!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://bb.ringingworld.co.uk/search?dove_tower=10946\" target=\"_blank\" rel=\"noreferrer noopener\">Tower\'s BellBoard</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button -->\n<div class=\"wp-block-button\"><a class=\"wp-block-button__link wp-element-button\" href=\"https://dove.cccbr.org.uk/tower/10946\" target=\"_blank\" rel=\"noreferrer noopener\">Dove\'s Guide</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"general info\"},\"style\":{\"spacing\":{\"padding\":{\"right\":\"var:preset|spacing|superbspacing-xsmall\",\"left\":\"var:preset|spacing|superbspacing-xsmall\",\"top\":\"var:preset|spacing|superbspacing-medium\",\"bottom\":\"var:preset|spacing|superbspacing-medium\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"padding-top:var(--wp--preset--spacing--superbspacing-medium);padding-right:var(--wp--preset--spacing--superbspacing-xsmall);padding-bottom:var(--wp--preset--spacing--superbspacing-medium);padding-left:var(--wp--preset--spacing--superbspacing-xsmall)\"><!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column {\"width\":\"20%\",\"style\":{\"spacing\":{\"padding\":{\"left\":\"20px\",\"right\":\"20px\",\"top\":\"20px\",\"bottom\":\"20px\"},\"blockGap\":\"30px\"}},\"backgroundColor\":\"mono-3\"} -->\n<div class=\"wp-block-column has-mono-3-background-color has-background\" style=\"padding-top:20px;padding-right:20px;padding-bottom:20px;padding-left:20px;flex-basis:20%\"><!-- wp:paragraph -->\n<p><strong>Town</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>District</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"layout\":{\"columnSpan\":1,\"rowSpan\":1}}} -->\n<p><strong>Dedication</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>P<strong>ractice Nights</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Service Nights</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p><strong>Accesibility</strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {\"width\":\"80%\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"20px\",\"bottom\":\"20px\",\"left\":\"20px\",\"right\":\"20px\"},\"blockGap\":\"30px\"}}} -->\n<div class=\"wp-block-column\" style=\"padding-top:20px;padding-right:20px;padding-bottom:20px;padding-left:20px;flex-basis:80%\"><!-- wp:paragraph -->\n<p>Elstree</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>Watford</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>St. Nicholas</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>None</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"style\":{\"layout\":{\"columnSpan\":1,\"rowSpan\":1}}} -->\n<p>None</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:shortcode -->\nGround floor ringing, Toilets not available\n<!-- /wp:shortcode --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"comments\"},\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|superbspacing-small\",\"bottom\":\"var:preset|spacing|superbspacing-small\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:var(--wp--preset--spacing--superbspacing-small);margin-bottom:var(--wp--preset--spacing--superbspacing-small)\"><!-- wp:paragraph {\"metadata\":{\"name\":\"Comment shortcodes\"}} -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"metadata\":{\"name\":\"Comment shortcodes\"}} -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"metadata\":{\"name\":\"Comment shortcodes\"}} -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {\"metadata\":{\"name\":\"Comment shortcodes\"}} -->\n<p></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"metadata\":{\"name\":\"contact info\"},\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|superbspacing-xsmall\",\"bottom\":\"var:preset|spacing|superbspacing-xsmall\"}}},\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:var(--wp--preset--spacing--superbspacing-xsmall);margin-bottom:var(--wp--preset--spacing--superbspacing-xsmall)\"><!-