INSERT INTO `wp_posts` VALUES (54,1,'2024-10-10 11:34:05','2024-10-10 11:34:05','<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|superbspacing-medium\",\"bottom\":\"var:preset|spacing|superbspacing-medium\"},\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"fontSize\":\"superbfont-small\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-superbfont-small-font-size\" style=\"margin-top:var(--wp--preset--spacing--superbspacing-medium);margin-bottom:var(--wp--preset--spacing--superbspacing-medium)\"><!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">Patrons</h2>\n<!-- /wp:heading -->\n\n<!-- wp:shortcode -->\n[display_patrons]\n<!-- /wp:shortcode --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|superbspacing-medium\",\"bottom\":\"var:preset|spacing|superbspacing-medium\"},\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"fontSize\":\"superbfont-small\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-superbfont-small-font-size\" style=\"margin-top:var(--wp--preset--spacing--superbspacing-medium);margin-bottom:var(--wp--preset--spacing--superbspacing-medium)\"><!-- wp:heading {\"textAlign\":\"center\"} -->\n<h2 class=\"wp-block-heading has-text-align-center\">President</h2>\n<!-- /wp:heading -->\n\n<!-- wp:shortcode -->\n[display_president]\n<!-- /wp:shortcode --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|superbspacing-medium\",\"bottom\":\"var:preset|spacing|superbspacing-medium\"},\"blockGap\":\"var:preset|spacing|superbspacing-xxsmall\"}},\"fontSize\":\"superbfont-small\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-superbfont-small-font-size\" style=\"margin-top:var(--wp--preset--spacing--superbspacing-medium);margin-bottom:var(--wp--preset--spacing--