acing\":{\"blockGap\":\"var:preset|spacing|superbspacing-small\",\"padding\":{\"top\":\"var:preset|spacing|superbspacing-xsmall\",\"bottom\":\"var:preset|spacing|superbspacing-xsmall\",\"left\":\"var:preset|spacing|superbspacing-large\",\"right\":\"var:preset|spacing|superbspacing-large\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}},\"border\":{\"radius\":\"20px\"}},\"backgroundColor\":\"vivid-cyan-blue\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"wrap\",\"justifyContent\":\"center\",\"orientation\":\"vertical\"}} -->\n<div class=\"wp-block-group alignwide has-vivid-cyan-blue-background-color has-background\" style=\"border-radius:20px;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--superbspacing-xsmall);padding-right:var(--wp--preset--spacing--superbspacing-large);padding-bottom:var(--wp--preset--spacing--superbspacing-xsmall);padding-left:var(--wp--preset--spacing--superbspacing-large)\"><!-- wp:group {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"}},\"layout\":{\"type\":\"constrained\",\"justifyContent\":\"center\",\"contentSize\":\"600px\"}} -->\n<div class=\"wp-block-group\"><!-- wp:heading {\"textAlign\":\"center\",\"textColor\":\"contrast-light\",\"fontSize\":\"superbfont-xlarge\"} -->\n<h2 class=\"wp-block-heading has-text-align-center has-contrast-light-color has-text-color has-superbfont-xlarge-font-size\"><strong>Association Diary (Google Calendar)</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {\"align\":\"center\",\"textColor\":\"contrast-light\",\"fontSize\":\"superbfont-medium\"} -->\n<p class=\"has-text-align-center has-contrast-light-color has-text-color has-superbfont-medium-font-size\">Get more information on upcoming events and practise nights</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:buttons {\"style\":{\"spacing\":{\"blockGap\":\"var:preset|spacing|superbspacing-xsmall\"},\"layout\":{\"selfStretch\":\"fill\",\"flexSize\":null}},\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"textColor\":\"contrast-light\",\"className\":\"is-style-outline\",\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|contrast-light\"}}}},\"fontSize\":\"superbfont-small\"} -->\n<div class=\"wp-block-button has-custom-font-size is-style-outline has-superbfont-small-font-size\"><a class=\"wp-block-button__link has-contrast-light-color has-text-color has-link-color wp-element-button\">Go to calendar</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:template-part {\"slug\":\"footer\",\"theme\":\"greenleaf-blog\",\"area\":\"footer\"} /-->','Front Page','Displays your site\'s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.','inherit','closed','closed','','15-revision-v1','','','2024-10-10 14:59:17','2024-10-10 14:59:17','',15,'http://hcacr.local/?p=80',0,'revision','',0);
