INSERT INTO `wp_posts` VALUES (172,1,'2022-09-08 00:00:00','2022-09-08 00:00:00','Click here for the Central Council Guidance on ringing and other matters in response to the sad news of the death of Her Majesty the Queen.\n<br>\n<br>We particularly recommend that organisers read the guidance from the CofE linked there, which is on a second version at the time of writing.\n<br>\n<br>','[Updated] Church of England ringing arrangements following the death of Her Majesty the Queen','','trash','open','open','','updated-church-of-england-ringing-arrangements-following-the-death-of-her-majesty-the-queen__trashed','','','2024-10-13 17:50:05','2024-10-13 17:50:05','',0,'http://hcacr.local/updated-church-of-england-ringing-arrangements-following-the-death-of-her-majesty-the-queen/',0,'post','',0);
