INSERT INTO `wp_posts` VALUES (208,1,'2020-01-28 00:00:00','2020-01-28 00:00:00','Why not take up bellringing as part of your county\'s year of culture? New people always welcome, aged 7 to 127. Why not find your local ringing church on this website and get in touch?\n  <br><a href=\"https://cccbr.org.uk/bellringing/what-is-bell-ringing/\">What is bellringing?</a>\n  <br>Note: HCACR has no formal affiliation with Hertfordshire Year of Culture.','Hertfordshire Year of Culture 2020 - why not take up bellringing as a new sport and hobby?!','','trash','open','open','','hertfordshire-year-of-culture-2020-why-not-take-up-bellringing-as-a-new-sport-and-hobby__trashed','','','2024-10-13 17:50:09','2024-10-13 17:50:09','',0,'http://hcacr.local/hertfordshire-year-of-culture-2020-why-not-take-up-bellringing-as-a-new-sport-and-hobby/',0,'post','',0);
