INSERT INTO `wp_posts` VALUES (437,1,'2022-11-23 00:00:00','2022-11-23 00:00:00','The new frame at St Michael\'s is in, the newly-augmented 12 (+ sharp 2nd) are hung in it, and test ringing was a success! Video on the county facebook page. St Michael\'s was previously a 10. \nThe old number four was too thin to re-tune and so is being kept in the old frame, hung dead - the 14th bell in the tower.','Hertford has a new 12! St Michael\'s Bishop\'s Stortford is back!','','publish','closed','open','','hertford-has-a-new-12-st-michaels-bishops-stortford-is-back','','','2022-11-23 00:00:00','2022-11-23 00:00:00','',0,'http://hcacr.local/hertford-has-a-new-12-st-michaels-bishops-stortford-is-back/',0,'post','',0);
