INSERT INTO `wp_posts` VALUES (440,1,'2022-09-09 00:00:00','2022-09-09 00:00:00','Many ringers have struggled to understand the guidance for this weekend, but the CCCBR has just sent around a remarkably clear email:\n<br>From: Vicki Chapman\n<br>Date: Fri, Sep 9, 2022 at 9:17 PM\n<br>Subject:Further guidance on open ringing for the proclamation announcement\n<br>To:\n<br>\n<br>Following further discussion and interpretation of the CofE guidance, we suggest the following for open ringing following the proclamation of the new Monarch expected on Saturday.\n<br>\n<br>Open ringing from 11am (BST) on Saturday (D+1) following the proclamation announcement until the flags are lowered again at 1pm (BST) on Sunday.\n<br>\n<br>Bells should then revert to being rung muffled/half muffled until the end of the day of the state funeral.\n<br>\n<br>This is suggested guidance, please do liaise with local church authorities for local arrangements.','Ringing arrangements for Saturday 10th/Sunday 11th September related to the Accession and Proclamation of HM King Charles III','','publish','closed','open','','ringing-arrangements-for-saturday-10th-sunday-11th-september-related-to-the-accession-and-proclamation-of-hm-king-charles-iii','','','2022-09-09 00:00:00','2022-09-09 00:00:00','',0,'http://hcacr.local/ringing-arrangements-for-saturday-10th-sunday-11th-september-related-to-the-accession-and-proclamation-of-hm-king-charles-iii/',0,'post','',0);
INSERT INTO `wp_posts` VALUES (441,1,'2022-09-08 00:00:00','2022-09-08 00:00:00','Click here for the Central Council Guidance on ringing and other matters in response to the sad news of the death of Her Majesty the Queen.\n<br>\n<br>We particularly recommend that organisers read the guidance from the CofE linked there, which is on a second version at the time of writing.\n<br>\n<br>','[Updated] Church of England ringing arrangements following the death of Her Majesty the Queen','','publish','closed','open','','updated-church-of-england-ringing-arrangements-following-the-death-of-her-majesty-the-queen','','','2022-09-08 00:00:00','2022-09-08 00:00:00','',0,'http://hcacr.local/updated-church-of-england-ringing-arrangements-following-the-death-of-her-majesty-the-queen/',0,'post','',0);
