INSERT INTO `wp_posts` VALUES (443,1,'2022-07-12 00:00:00','2022-07-12 00:00:00','The HCACR rules have had two minor updates as of the last AGM:\n<br>- Rule 7.1 changed to reduce the number of trustees from 25 to 9, previously all members of the management committee were trustees; and\n<br>- Rule 13.6 added to allow online meetings to be officially held.','HCACR rules updates','','publish','closed','open','','hcacr-rules-updates','','','2022-07-12 00:00:00','2022-07-12 00:00:00','',0,'http://hcacr.local/hcacr-rules-updates/',0,'post','',0);
